	"aW9uL3JlZmVyZW5jZXMvbnZjZi11aS1hZGRvbi5tZFVUBQABAKbOElBLAQIUABQACAAAAAAAIQBL" +
	"QjWoABYAAAAWAAA+AAkAAAAAAAAAAAAAANeBAwBkYXRhL252Y2Ytc2VsZi1tYW5hZ2VkLWluc3Rh" +
	"bGxhdGlvbi9yZWZlcmVuY2VzL3B1bGwtc2VjcmV0cy5tZFVUBQABAKbOElBLBQYAAAAAFwAXAK8J" +
	"AABMmAMAAAA="

var (
	skillDataOnce sync.Once
	skillDataFS   fs.FS
	skillDataErr  error
)

func FS() fs.FS {
	skillDataOnce.Do(func() {
		body, err := base64.StdEncoding.DecodeString(skillDataZipBase64)
		if err != nil {
			skillDataErr = fmt.Errorf("decode embedded skill data: %w", err)
			return
		}
		reader, err := zip.NewReader(bytes.NewReader(body), int64(len(body)))
		if err != nil {
			skillDataErr = fmt.Errorf("open embedded skill data: %w", err)
			return
		}
		skillDataFS = reader
	})
	if skillDataErr != nil {
		return errFS{err: skillDataErr}
	}
	return skillDataFS
}

type errFS struct {
	err error
}

func (e errFS) Open(string) (fs.File, error) {
	return nil, e.err
}
